STORY = [('cindy', '저 할게요, 일박 이일.', 'I will do it, two days and one night.', [(256, '저 할게요')], ''), ('byun', '너 방금 뭐라고? 내가 널 어떻게 이 자리까지 올렸는데!', 'What did you just say? Do you know how hard I worked to raise you to this position!', [(257, '너 방금 뭐라고'), (265, '내가 널 어떻게 이 자리까지 올렸는데')], ''), ('byun', '왜 예능을 하겠대? 톱스타가 예능을 하니?', 'Why do you want to do variety? Do top stars do variety shows?', [(266, '왜 예능을 하겠대')], ''), ('cindy', '나도 그런 계산 다 해 봤어요.', 'I have already thought through all those calculations too.', [(268, '나도 그런 계산 다 해봤어요')], ''), ('cindy', '예능을 시작하고 오히려 수많은 팬층을 확보했잖아요.', 'After starting variety shows, stars actually won over huge fan bases.', [(272, '예능 프로그램을 시작하고'), (273, '오히려 더 수많은 팬층을 확보하면서')], ''), ('byun', '예능이 정 하고 싶다면 알아볼게. 근데 그건 안 돼.', 'If you really want variety, I will look into others. But not that show.', [(284, '알아볼게'), (285, '안 돼')], ''), ('cindy', '나 십 년 동안 시키는 대로 다 했잖아요.', 'For ten years, I did everything you told me to do.', [(286, '동안 하자는 대로 시키는 대로 다 했잖아요')], ''), ('cindy', '그러니까 이번엔 내가 하자는 대로 해요.', 'So this time, do things the way I want.', [(288, '그러니까 이번엔 내가 하자는 대로 해요')], ''), ('manager', '신디야, 그거 밖에서 자고 아무거나 먹어야 돼.', 'Cindy, on that show you have to sleep outdoors and eat anything.', [(289, '신디야 그거 막 밖에서 자고 아무거나 먹어야 되고')], ''), ('cindy', '오빠, 생각하는 걸 다 말로 하지 말란 말이야.', 'Hey, stop saying everything you think out loud.', [(293, '생각하는 걸 다 말로 하지 말란 말이야')], ''), ('cindy', '근데 나 프로야, 오빠. 내가 방송 위해서 못 참을 것 같아?', 'Besides, I am a pro. Do you think I cannot endure that for a broadcast?', [(298, '근데 나 프로야, 오빠'), (299, '못 참을 거 같아')], ''), ('cindy', '나 지금도 봐, 얼마나 털털해.', 'Look at me even right now, how easygoing I am.', [(300, '나 지금도 봐'), (301, '얼마나 털털해')], '')]
